<script setup>
import { computed, ref } from 'vue';
import { Head, router } from '@inertiajs/vue3';
import AppLayout from '../Layouts/AppLayout.vue';
const props = defineProps({ kind:String, items:Object, records:[Object,Array], tenders:Object, categories:Array, settings:Object, company:Object, resetToken:String, users:Array });
const title=ref(''), recipient=ref(''), context=ref(''), text=ref(''), spreadsheet=ref(null), result=ref(null), error=ref(''), loading=ref(false), parsed=ref([]), template=ref({name:'',channel:'whatsapp',subject:'',body:'',active:true}), event=ref({title:'',starts_at:'',ends_at:'',priority:'Normal'}), config=ref({...props.settings}), resetToken=ref('');
const labels={inventory:'Inventario','tender-ai':'IA Licitaciones','offer-calculator':'Calculadora de Oferta','document-generator':'Generador de Documentos',notifications:'Notificaciones',calendar:'Calendario',training:'Capacitación',settings:'Configuración',sops:'Procedimientos Operativos'};
const label=computed(()=>labels[props.kind]||'Módulo'); const rows=computed(()=>props.items?.data||props.records?.data||props.records||props.tenders?.data||[]);
async function api(url,payload,file=false){loading.value=true;error.value='';try{let body=payload,headers={Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content};if(file){body=new FormData();Object.entries(payload).forEach(([key,value])=>body.append(key,value));}else{headers['Content-Type']='application/json';body=JSON.stringify(payload)}const response=await fetch(url,{method:'POST',headers,body});const data=await response.json();if(!response.ok)throw new Error(data.message||'No fue posible completar la acción.');result.value=data;return data}catch(e){error.value=e.message}finally{loading.value=false}}
async function generate(){await api('/generador-documentos',{type:title.value||'carta_presentacion',recipient:recipient.value,context:context.value,...(props.company||{})});}
function saveTemplate(){router.post('/notificaciones',template.value)}
function updateTemplate(row){router.put(`/notificaciones/${row.id}`,{...row,active:!row.active})}
function deleteTemplate(id){if(confirm('¿Eliminar plantilla?'))router.delete(`/notificaciones/${id}`)}
function saveEvent(){router.post('/calendario',event.value)}
function completeEvent(row){router.put(`/calendario/${row.id}`,{...row,completed:!row.completed})}
function saveSettings(){router.put('/configuracion',{settings:config.value})}
function uploadLogo(e){router.post('/configuracion/logo',{logo:e.target.files[0]},{forceFormData:true})}
function reset(){if(confirm('Esto eliminará la configuración de empresa.'))router.post('/configuracion/reset',{confirmation_token:resetToken.value})}
function changeRole(user, role){router.put(`/configuracion/usuarios/${user.id}/rol`,{role})}
</script>
<template><Head :title="label"/><AppLayout><main class="specialized"><header><h1>{{label}}</h1><p>Datos y acciones procesados por el servidor.</p></header>
<section v-if="kind==='document-generator'" class="card"><p>Los datos de empresa configurados se usan como valores predeterminados.</p><label>Tipo<input v-model="title" placeholder="carta_presentacion"></label><label>Destinatario<input v-model="recipient"></label><label>Contexto<textarea v-model="context"></textarea></label><button @click="generate">Generar documento</button><div v-for="row in rows" :key="row.id"><a :href="`/generador-documentos/${row.id}/pdf`">PDF: {{row.title}}</a></div></section>
<section v-else-if="kind==='notifications'" class="card"><h2>Plantillas (vista previa, sin envío al servidor)</h2><label>Nombre<input v-model="template.name"></label><label>Canal<select v-model="template.channel"><option value="whatsapp">WhatsApp</option><option value="email">Email</option></select></label><label>Asunto<input v-model="template.subject"></label><label>Mensaje<textarea v-model="template.body"></textarea></label><button @click="saveTemplate">Guardar plantilla</button><article v-for="row in rows" :key="row.id"><strong>{{row.name}}</strong> · {{row.channel}} · {{row.active?'Activa':'Inactiva'}}<pre>{{row.subject}}\n{{row.body}}</pre><button @click="updateTemplate(row)">Activar / desactivar</button><button @click="deleteTemplate(row.id)">Eliminar</button></article></section>
<section v-else-if="kind==='calendar'" class="card"><h2>Calendario</h2><label>Título<input v-model="event.title"></label><label>Inicio<input v-model="event.starts_at" type="datetime-local"></label><label>Fin<input v-model="event.ends_at" type="datetime-local"></label><label>Prioridad<select v-model="event.priority"><option>Baja</option><option>Normal</option><option>Alta</option><option>Crítica</option></select></label><button @click="saveEvent">Crear evento</button><table><tr><th>Evento</th><th>Inicio</th><th>Origen</th><th>Estado</th><th></th></tr><tr v-for="row in rows" :key="row.id"><td>{{row.title}}</td><td>{{row.starts_at}}</td><td>{{row.derived?'Derivado':'Manual'}}</td><td>{{row.completed?'Completado':'Pendiente'}}</td><td><button v-if="!row.derived" @click="completeEvent(row)">Completar</button></td></tr></table></section>
<section v-else-if="kind==='settings'" class="card"><label>Empresa<input v-model="config.name"></label><label>Dirección<input v-model="config.address"></label><label>RTN<input v-model="config.tax_id"></label><label>Logo<input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadLogo"></label><button @click="saveSettings">Guardar configuración</button><a class="button" href="/configuracion/preview.pdf" target="_blank">Vista previa PDF</a><h2>Controles administrativos</h2><table><tr><th>Usuario</th><th>Rol</th></tr><tr v-for="user in users" :key="user.id"><td>{{user.name}}<small>{{user.email}}</small></td><td><select :value="user.role" @change="changeRole(user,$event.target.value)"><option value="operator">Operador</option><option value="admin">Administrador</option></select></td></tr></table><button @click="router.post('/configuracion/seed')">Sembrar datos demo</button><label>Token de confirmación para reset<input v-model="resetToken"></label><small>Token: {{props.resetToken}}</small><button class="danger" @click="reset">Restablecer configuración</button></section>
<section v-else-if="kind==='sops'" class="card"><article v-for="(sop,index) in rows" :key="sop.title"><h2>{{sop.title}}</h2><p>{{sop.content}}</p><a class="button" :href="`/sops/${index}/pdf`">Descargar PDF</a></article></section>
<section v-else class="card"><p>Este módulo conserva su consulta del servidor.</p></section><p v-if="error" class="error">{{error}}</p><pre v-if="result">{{result}}</pre></main></AppLayout></template>
<style scoped>.specialized{padding:1.5rem;max-width:1100px;margin:auto}.card{background:#fff;border:1px solid #e2e8f0;border-radius:.75rem;padding:1rem}.card label{display:block;margin:.7rem 0;font-weight:600}.card input,.card textarea,.card select{display:block;width:100%;box-sizing:border-box;margin-top:.2rem;padding:.55rem;border:1px solid #cbd5e1;border-radius:.4rem}button,.button{display:inline-block;margin:.4rem .4rem .4rem 0;padding:.55rem .9rem;background:#0057b8;color:#fff;border:0;border-radius:.4rem;text-decoration:none;cursor:pointer}.danger{background:#b91c1c}table{width:100%;border-collapse:collapse;margin:1rem 0}td,th{padding:.55rem;border-bottom:1px solid #e2e8f0;text-align:left}article{padding:1rem 0;border-bottom:1px solid #e2e8f0}.error{color:#b91c1c}pre{white-space:pre-wrap;background:#f8fafc;padding:1rem}@media(max-width:700px){.specialized{padding:1rem}}</style>
